#!/usr/bin/env node
// Inlines dashboard/* into src/dashboard.gen.js (git-ignored) so the Worker serves them with its own headers.
// wrangler dev / wrangler deploy run this through [build] in wrangler.toml; `npm test` runs it first too.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const read = (f) => fs.readFileSync(path.join(ROOT, 'dashboard', f));
const out = [
  '// GENERATED by scripts/bundle-dashboard.mjs from dashboard/*. Do not edit.',
  `export const INDEX_HTML = ${JSON.stringify(read('index.html').toString('utf8'))};`,
  `export const APP_JS = ${JSON.stringify(read('app.js').toString('utf8'))};`,
  `export const APP_CSS = ${JSON.stringify(read('app.css').toString('utf8'))};`,
  `export const MANIFEST = ${JSON.stringify(JSON.stringify(JSON.parse(read('manifest.webmanifest').toString('utf8'))))};`,
  `export const ICON_PNG_B64 = ${JSON.stringify(read('icon.png').toString('base64'))};`,
  '',
].join('\n');
fs.writeFileSync(path.join(ROOT, 'src', 'dashboard.gen.js'), out);
console.log('dashboard.gen.js written');
